              <div className="flex-1 overflow-y-auto no-scrollbar px-3 space-y-1">
                <div className="text-[11px] text-[var(--muted)] font-semibold px-2 py-1 all-caps-label">
                  历史咨询记录
                </div>
                {chatSessions.map((session) => (
                  <button
                    key={session.id}
                    onClick={() => setActiveSessionId(session.id)}
                    className={`w-full text-left p-2.5 rounded-lg flex items-center gap-2.5 transition duration-150 ${activeSessionId === session.id ? 'bg-brand/10 text-brand font-medium' : 'hover:bg-[var(--bg)] text-[var(--fg)]'}`}
                  >
                    <svg className={`w-4 h-4 ${activeSessionId === session.id ? 'text-brand' : 'text-[var(--muted)]'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z"></path>
                    </svg>
                    <span className="truncate text-xs">{session.title}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Bottom Controls */}
            <div className="p-3 border-t border-[var(--border)] space-y-2">
              {/* Theme Toggle */}
              <div className="flex items-center justify-between p-2 rounded-lg bg-[var(--bg)]">
                <span className="text-xs text-[var(--muted)]">外观模式</span>
                <button
                  onClick={() => setTheme(prev => prev === "light" ? "dark" : "light")}
                  className="p-1 rounded-md hover:bg-[var(--border)] transition"
                  title="切换亮/暗色主题"
                >
                  {theme === "light" ? (
                    <svg className="w-4 h-4 text-gray-700" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z"></path>
                    </svg>
                  ) : (
                    <svg className="w-4 h-4 text-yellow-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364-6.364l-.707.707M6.343 17.657l-.707.707m2.828 0l-.707-.707m2.828-11.314l-.707-.707M6.343 6.343l-.707-.707M12 5a7 7 0 100 14 7 7 0 000-14z"></path>
                    </svg>
                  )}
                </button>
              </div>

              {/* Status Indicator */}
              <div className="flex items-center gap-2 px-2 py-1 text-xs text-brand">
                <span className="w-2 h-2 rounded-full bg-brand animate-ping"></span>
                <span>生产数据集直连可用</span>
              </div>
            </div>
          </aside>

          {/* Main workspace */}
          <main className="flex-1 flex flex-col overflow-hidden bg-[var(--bg)] relative">

            {/* Nav Filter Bar */}
            <header className="h-14 border-b border-[var(--border)] bg-[var(--surface)] flex items-center justify-between px-6 z-10">
              <div className="flex items-center gap-2 overflow-x-auto no-scrollbar py-1">
                {categories.map(cat => (
                  <button
                    key={cat}
                    onClick={() => setSelectedCategory(cat)}
                    className={`px-3 py-1.5 text-xs rounded-full font-medium transition whitespace-nowrap ${selectedCategory === cat ? 'bg-brand text-white' : 'bg-[var(--bg)] hover:bg-[var(--border)] text-[var(--muted)]'}`}
                  >
                    {cat}
                  </button>
                ))}
              </div>

              {/* Top Search bar */}
              <div className="relative w-64 hidden md:block">
                <span className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                  <svg className="w-4 h-4 text-[var(--muted)]" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
                  </svg>
                </span>
                <input
                  type="text"
                  placeholder="检索数据集名称/标签..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full py-1.5 pl-9 pr-4 text-xs bg-[var(--bg)] border border-[var(--border)] rounded-full focus:outline-none focus:border-brand transition"
                />
              </div>
            </header>

            {/* Split Panel Area */}
            <div className="flex-1 flex overflow-hidden">

              {/* Left pane: Kimi Chat Agent */}
              <div className={`flex-1 flex flex-col justify-between ${inspectingDataset ? 'max-w-xl border-r border-[var(--border)]' : ''} transition-all duration-300`}>

                {/* Chat Message Box */}
                <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-[var(--bg)]">
                  {(chatMessages[activeSessionId] || []).length === 0 ? (
                    // Kimi Home Welcome Screen
                    <div className="h-full flex flex-col justify-center items-center max-w-xl mx-auto space-y-8 select-none">
                      <div className="flex flex-col items-center text-center space-y-4">
                        <div className="w-16 h-16 rounded-full bg-brand flex items-center justify-center text-white text-3xl font-extrabold shadow-md">
                          K
                        </div>
                        <h2 className="text-xl font-bold heading-large">你好，我是 Kimi 生产级数据专家</h2>
                        <p className="text-sm text-[var(--muted)] max-w-md">
                          支持跨分类检索各类大模型预训练、SFT微调、RLHF偏好对齐等生产级别权威开源数据集。
                        </p>
                      </div>

                      {/* Interactive suggestion cards */}
                      <div className="grid grid-cols-2 gap-3 w-full">
                        <button
                          onClick={() => handleSuggestionClick("大模型预训练数据有推荐吗？")}
                          className="p-3 text-left border border-[var(--border)] bg-[var(--surface)] hover:border-brand rounded-xl transition duration-150 group"
                        >
                          <div className="font-semibold text-xs text-brand group-hover:underline">预训练数据指南</div>
                          <div className="text-[11px] text-[var(--muted)] mt-1">推荐清洗完备、支持中文及英文超大规模网页预训练的数据。</div>
                        </button>
                        <button
                          onClick={() => handleSuggestionClick("帮我对比一下 ShareGPT 和 MOSS")}
                          className="p-3 text-left border border-[var(--border)] bg-[var(--surface)] hover:border-brand rounded-xl transition duration-150 group"
                        >
                          <div className="font-semibold text-xs text-brand group-hover:underline">对话指令对齐</div>
                          <div className="text-[11px] text-[var(--muted)] mt-1">对比学术微调集与真实人类 ChatGPT 对话的数据集。</div>
                        </button>
                        <button
                          onClick={() => handleSuggestionClick("RLHF 偏好数据集有哪些？")}
                          className="p-3 text-left border border-[var(--border)] bg-[var(--surface)] hover:border-brand rounded-xl transition duration-150 group"
                        >
                          <div className="font-semibold text-xs text-brand group-hover:underline">偏好对齐与打分</div>
                          <div className="text-[11px] text-[var(--muted)] mt-1">了解包含 GPT-4 自动多维度客观打分与评估的数据集。</div>
                        </button>
                        <button
                          onClick={() => handleSuggestionClick("COCO 数据集格式说明")}
                          className="p-3 text-left border border-[var(--border)] bg-[var(--surface)] hover:border-brand rounded-xl transition duration-150 group"
                        >
                          <div className="font-semibold text-xs text-brand group-hover:underline">多模态与视觉数据</div>
                          <div className="text-[11px] text-[var(--muted)] mt-1">了解计算机视觉中著名的 COCO 实例分割及标注格式。</div>
                        </button>
                      </div>
                    </div>
                  ) : (
                    // Active chat thread representation
                    <div className="space-y-6">
                      {chatMessages[activeSessionId].map((msg, index) => (
                        <div key={index} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                          <div className="flex gap-3 max-w-[85%]">
                            {msg.sender === 'kimi' && (
                              <div className="w-8 h-8 rounded-full bg-brand flex items-center justify-center text-white font-extrabold text-xs shrink-0 select-none">
                                K
                              </div>
                            )}
                            <div className={`p-4 rounded-2xl text-xs leading-relaxed whitespace-pre-wrap ${msg.sender === 'user' ? 'chat-bubble-user text-right' : 'chat-bubble-kimi text-left'}`}>
                              {msg.text}
                            </div>
                          </div>
                        </div>
                      ))}

                      {/* Thinking Loader */}
                      {isThinking && (
                        <div className="flex justify-start">
                          <div className="flex gap-3">
                            <div className="w-8 h-8 rounded-full bg-brand flex items-center justify-center text-white font-extrabold text-xs shrink-0 pulse-search">
                              K
                            </div>
                            <div className="p-4 rounded-2xl chat-bubble-kimi flex items-center gap-2">
                              <span className="text-xs text-[var(--muted)] animate-pulse">
                                {searchWeb ? "正在联网搜索行业数据并整合..." : "分析数据格式中..."}
                              </span>
                              <div className="flex gap-1">
                                <span className="w-1.5 h-1.5 rounded-full bg-brand animate-bounce" style={{animationDelay:'0ms'}}></span>
                                <span className="w-1.5 h-1.5 rounded-full bg-brand animate-bounce" style={{animationDelay:'150ms'}}></span>
                                <span className="w-1.5 h-1.5 rounded-full bg-brand animate-bounce" style={{animationDelay:'300ms'}}></span>
                              </div>
                            </div>
                          </div>
                        </div>
                      )}

                      <div ref={chatEndRef} />
                    </div>
                  )}
                </div>

                {/* Bottom Input Area */}
                <div className="p-4 bg-[var(--surface)] border-t border-[var(--border)]">
                  <div className="max-w-2xl mx-auto border border-[var(--border)] rounded-2xl bg-[var(--bg)] p-2 focus-within:border-brand transition duration-150">
                    <textarea
                      rows="2"
                      placeholder="咨询数据集方案或输入您感兴趣的数据需求..."
                      value={inputValue}
                      onChange={(e) => setInputValue(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                          e.preventDefault();
                          handleSendMessage(inputValue);
                        }
                      }}
                      className="w-full px-3 py-2 text-xs bg-transparent focus:outline-none resize-none no-scrollbar"
                    />

                    <div className="flex items-center justify-between border-t border-[var(--border)] pt-2 px-2 mt-1">
                      {/* Left: Attachment & Web search toggler */}
                      <div className="flex items-center gap-3">
                        <button className="text-[var(--muted)] hover:text-brand transition" title="上传本地参考文档">
                          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15.172 7l-6.586 6.586a2 2 0 102.828 2.828l6.414-6.586a4 4 0 00-5.656-5.656l-6.415 6.585a6 6 0 108.486 8.486L20.5 13"></path>
                          </svg>
                        </button>

                        {/* Kimi specific online search switcher */}
                        <button 
                          onClick={() => setSearchWeb(prev => !prev)}
                          className={`flex items-center gap-1 px-2.5 py-1 rounded-full text-[11px] font-medium transition ${searchWeb ? 'bg-brand/10 text-brand border border-brand/20' : 'bg-gray-100 dark:bg-zinc-800 text-[var(--muted)] border border-transparent'}`}
                        >
                          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9"></path>
                          </svg>
                          联网搜索
                        </button>
                      </div>

                      {/* Right: Send button */}
                      <button
                        onClick={() => handleSendMessage(inputValue)}
                        disabled={!inputValue.trim()}
                        className={`w-7 h-7 rounded-full flex items-center justify-center text-white transition ${inputValue.trim() ? 'bg-brand hover:bg-brand-hover' : 'bg-gray-300 dark:bg-zinc-700 cursor-not-allowed'}`}
                      >
                        <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M5 10l7-7m0 0l7 7m-7-7v18"></path>
                        </svg>
                      </button>
                    </div>
                  </div>
                </div>

              </div>

              {/* Right pane: Dataset Inspector / Card List */}
              <div className="flex-1 flex flex-col overflow-hidden bg-[var(--surface)]">

                {/* Secondary Header or search result counts */}
                <div className="p-4 border-b border-[var(--border)] flex items-center justify-between">
                  <span className="font-semibold text-xs text-[var(--muted)] all-caps-label">
                    数据资产目录 ({filteredDatasets.length})
                  </span>

                  {inspectingDataset && (
                    <button 
                      onClick={() => setInspectingDataset(null)}
                      className="text-xs text-brand hover:underline flex items-center gap-1 font-semibold"
                    >
                      <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M15 19l-7-7 7-7"></path>
                      </svg>
                      返回列表
                    </button>
                  )}
                </div>

                {/* Main panel inner content: Catalog list OR Detail Inspector */}
                <div className="flex-1 overflow-y-auto p-4">
                  {!inspectingDataset ? (
                    // Active Datasets List Representation
                    <div className="space-y-3">
                      {filteredDatasets.length === 0 ? (
                        <div className="text-center py-10 text-xs text-[var(--muted)]">
                          未检索到符合当前筛选条件的数据集
                        </div>
                      ) : (
                        filteredDatasets.map(ds => (
                          <div 
                            key={ds.id}
                            className="p-4 border border-[var(--border)] bg-[var(--surface)] hover:border-brand rounded-xl transition duration-150 cursor-pointer"
                            onClick={() => {
                              setInspectingDataset(ds);
                              setInspectorTab("overview");
                            }}
                          >
                            <div className="flex items-start justify-between">
                              <div>
                                <span className="inline-block px-2 py-0.5 text-[10px] bg-brand/10 text-brand rounded font-semibold mb-1">
                                  {ds.category}
                                </span>
                                <h3 className="font-bold text-sm text-[var(--fg)] hover:text-brand transition">{ds.name}</h3>
                              </div>
                              <span className="text-xs text-[var(--muted)] font-mono">{ds.size}</span>
                            </div>

                            <p className="text-xs text-[var(--muted)] mt-2 line-clamp-2 leading-relaxed">
                              {ds.description}
                            </p>

                            <div className="mt-3 flex flex-wrap gap-1.5">
                              {ds.tags.map(tag => (
                                <span key={tag} className="px-2 py-0.5 bg-[var(--bg)] text-[var(--muted)] rounded-full text-[10px]">
                                  #{tag}
                                </span>
                              ))}
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  ) : (
                    // Deep Detail Inspector (Active Dataset selected)
                    <div className="space-y-4">

                      {/* Dataset Header */}
                      <div className="p-4 border border-[var(--border)] rounded-xl bg-[var(--bg)]">
                        <span className="px-2 py-0.5 text-[10px] bg-brand/10 text-brand rounded font-semibold">
                          {inspectingDataset.category}
                        </span>
                        <h2 className="text-lg font-bold mt-2 heading-large">{inspectingDataset.name}</h2>

                        <div className="grid grid-cols-2 gap-y-2 gap-x-4 mt-3 text-xs border-t border-[var(--border)] pt-3">
                          <div>
                            <span className="text-[var(--muted)]">发行团队: </span>
                            <span className="font-semibold">{inspectingDataset.source}</span>
                          </div>
                          <div>
                            <span className="text-[var(--muted)]">数据许可证: </span>
                            <span className="font-semibold text-brand underline cursor-pointer">{inspectingDataset.license}</span>
                          </div>
                          <div>
                            <span className="text-[var(--muted)]">数据规模: </span>
                            <span className="font-semibold font-mono">{inspectingDataset.size}</span>
                          </div>
                        </div>
                      </div>

                      {/* Detail tabs */}
                      <div className="border-b border-[var(--border)] flex gap-4">
                        {["overview", "schema", "preview", "sdk"].map((tab) => (
                          <button
                            key={tab}
                            onClick={() => setInspectorTab(tab)}
                            className={`pb-2 text-xs font-semibold relative transition ${inspectorTab === tab ? 'text-brand' : 'text-[var(--muted)] hover:text-[var(--fg)]'}`}
                          >
                            {tab === 'overview' && '基本概述'}
                            {tab === 'schema' && '结构 Schema'}
                            {tab === 'preview' && '样本 Preview'}
                            {tab === 'sdk' && '下载 SDK'}
                            {inspectorTab === tab && (
                              <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-brand rounded-full"></span>
                            )}
                          </button>
                        ))}
                      </div>

                      {/* Tab contents */}
                      <div className="py-2 text-xs">

                        {/* Tab 1: Overview */}
                        {inspectorTab === "overview" && (
                          <div className="space-y-3 leading-relaxed">
                            <p className="text-[var(--fg)]">{inspectingDataset.description}</p>

                            <h4 className="font-bold border-l-2 border-brand pl-2 text-brand mt-4 mb-2">特征维度量化分析</h4>
                            <div className="bg-[var(--bg)] p-3 rounded-lg border border-[var(--border)] space-y-1.5 font-mono">
                              {Object.entries(inspectingDataset.stats).map(([k, v]) => (
                                <div key={k} className="flex justify-between">
                                  <span className="text-[var(--muted)] capitalize">{k}:</span>
                                  <span className="font-semibold text-[var(--fg)]">{v}</span>
                                </div>
                              ))}
                            </div>
                          </div>
                        )}

                        {/* Tab 2: Schema Explorer */}
                        {inspectorTab === "schema" && (
                          <div className="border border-[var(--border)] rounded-lg overflow-hidden">
                            <table className="w-full text-left border-collapse">
                              <thead>
                                <tr className="bg-[var(--bg)] border-b border-[var(--border)] text-[var(--muted)]">
                                  <th className="p-2.5 font-semibold all-caps-label text-[10px]">字段名称</th>
                                  <th className="p-2.5 font-semibold all-caps-label text-[10px]">字段类型</th>
                                  <th className="p-2.5 font-semibold all-caps-label text-[10px]">解释描述</th>
                                </tr>
                              </thead>
                              <tbody>
                                {inspectingDataset.schema.map((item, idx) => (
                                  <tr key={idx} className="border-b border-[var(--border)] last:border-0 hover:bg-zinc-50 dark:hover:bg-zinc-800 transition">
                                    <td className="p-2.5 font-mono font-semibold text-brand">{item.field}</td>
                                    <td className="p-2.5 font-mono text-[var(--muted)]">{item.type}</td>
                                    <td className="p-2.5 text-[var(--fg)]">{item.desc}</td>
                                  </tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        )}

                        {/* Tab 3: Sample Preview */}
                        {inspectorTab === "preview" && (
                          <div className="space-y-3">
                            {inspectingDataset.preview.map((sample, sIdx) => (
                              <div key={sIdx} className="p-3 border border-[var(--border)] rounded-lg bg-[var(--bg)] space-y-2">
                                <div className="text-[10px] text-[var(--muted)] font-semibold border-b border-[var(--border)] pb-1.5 flex justify-between">
                                  <span>样本 #{sIdx + 1}</span>
                                  <span className="text-brand font-mono">Row Object</span>
                                </div>
                                {Object.entries(sample).map(([k, v]) => (
                                  <div key={k} className="space-y-1">
                                    <div className="font-semibold text-brand font-mono text-[10px]">{k}:</div>

                                    {/* Handle formatted chat preview vs flat text */}
                                    {k === 'chat' || k === 'conversations' ? (
                                      <div className="space-y-1.5 pl-2 border-l border-brand/30">
                                        {parseJsonHelper(v).map((msg, mIdx) => (
                                          <div key={mIdx} className="text-[11px]">
                                            <span className="font-bold text-brand uppercase text-[9px] mr-1">{msg.role || msg.from}:</span>
                                            <span className="text-[var(--fg)]">{msg.content || msg.value}</span>
                                          </div>
                                        ))}
                                      </div>
                                    ) : (
                                      <pre className="text-[11px] bg-[var(--surface)] p-2 rounded border border-[var(--border)] overflow-x-auto whitespace-pre-wrap font-mono leading-normal max-h-32 text-[var(--fg)]">
                                        {v}
                                      </pre>
                                    )}
                                  </div>
                                ))}
                              </div>
                            ))}
                          </div>
                        )}

                        {/* Tab 4: Download code block */}
                        {inspectorTab === "sdk" && (
                          <div className="space-y-3">
                            <div className="flex gap-2">
                              {["hf", "python", "curl"].map((fmt) => (
                                <button
                                  key={fmt}
                                  onClick={() => setSelectedFormatCode(fmt)}
                                  className={`px-3 py-1 rounded text-[10px] font-bold ${selectedFormatCode === fmt ? 'bg-brand text-white' : 'bg-[var(--bg)] text-[var(--muted)] hover:bg-[var(--border)]'}`}
                                >
                                  {fmt === 'hf' && 'Hugging Face CLI'}
                                  {fmt === 'python' && 'Python Stream'}
                                  {fmt === 'curl' && 'cURL Download'}
                                </button>
                              ))}
                            </div>

                            <div className="relative">
                              <pre className="p-3.5 bg-zinc-950 text-emerald-400 rounded-xl overflow-x-auto font-mono text-[11px] leading-relaxed shadow-inner">
                                {inspectingDataset.code[selectedFormatCode]}
                              </pre>

                              <button
                                onClick={() => {
                                  navigator.clipboard.writeText(inspectingDataset.code[selectedFormatCode]);
                                  alert("SDK Code Copied!");
                                }}
                                className="absolute top-2.5 right-2.5 p-1 text-zinc-400 hover:text-white bg-zinc-800 rounded transition"
                                title="复制代码至剪贴板"
                              >
                                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01"></path>
                                </svg>
                              </button>
                            </div>
                          </div>
                        )}

                      </div>

                    </div>
                  )}
                </div>

              </div>

            </div>

          </main>

        </div>
      );
    }

    const rootElement = document.getElementById("root");
    const root = ReactDOM.createRoot(rootElement);
    root.render(<App />);
  </script>
